const cr = variables.cr_preview_data || (input && input.cr) || {};
const domain = cr.domain;
const cfgType = cr.config_type;
if (!domain) return null;

const appsByDomain = variables.apps_by_domain || {};
let appRow = appsByDomain[domain];
if (!appRow || !appRow.id) {
  try {
    const UTIL = constants.UTIL_TABLE || '1687a012-ebd1-46a8-b648-ff13096f6b43';
    const r = await fetch(window.location.origin + '/api/tooljet-db/proxy/' + UTIL + '?name=eq.' + encodeURIComponent(domain) + '&select=id', { credentials:'include', headers:{ 'Tj-Workspace-Id': constants.WS } });
    const rs = await r.json();
    appRow = Array.isArray(rs) && rs[0] || null;
    if (appRow) {
      appsByDomain[domain] = appRow;
      await actions.setVariable('apps_by_domain', appsByDomain);
    }
  } catch (e) { console.warn('[loadFieldLabelsForCR] app lookup failed', e && e.message); }
}
if (!appRow) { console.warn('[loadFieldLabelsForCR] no app for domain', domain); return null; }

const ph = cr.page_handle || (cr.payload || {}).page_handle;
const TPL = constants.TPL_TABLE || 'f2ef887f-872d-466b-9b67-9a5bb3ce00eb';
const cache = variables.field_labels_by_page_key || {};

// LFL_V4 — direct page_key OR fallback: scan config_templates for this app, match by template_json.config_type_id via a chained lookup.
// Simpler pragmatic fallback: if exactly ONE config_templates row exists for this app, use it.
let pageKey = ph ? (appRow.id + '/' + ph) : null;
let tplObj = null;

if (pageKey && cache[pageKey]) { return cache[pageKey]; }

// Path 1: direct page_key lookup
if (pageKey) {
  try {
    const tr = await fetch(window.location.origin + '/api/tooljet-db/proxy/' + TPL + '?page_key=eq.' + encodeURIComponent(pageKey) + '&select=template_json', { credentials:'include', headers:{ 'Tj-Workspace-Id': constants.WS } });
    const trs = await tr.json();
    const tpl = Array.isArray(trs) && trs[0] && trs[0].template_json;
    if (tpl) tplObj = typeof tpl === 'string' ? JSON.parse(tpl || '{}') : (tpl || {});
  } catch (e) { console.warn('[loadFieldLabelsForCR] direct template fetch failed', e && e.message); }
}

// Path 2 (fallback): fetch ALL config_templates for this app; use if exactly one, else warn.
if (!tplObj) {
  try {
    const tr = await fetch(window.location.origin + '/api/tooljet-db/proxy/' + TPL + '?page_key=like.' + encodeURIComponent(appRow.id + '/%') + '&select=page_key,template_json', { credentials:'include', headers:{ 'Tj-Workspace-Id': constants.WS } });
    const trs = await tr.json();
    const rows = Array.isArray(trs) ? trs : [];
    console.log('[loadFieldLabelsForCR] fallback found', rows.length, 'config_templates rows for app_id=', appRow.id);
    if (rows.length === 1) {
      const row = rows[0];
      tplObj = typeof row.template_json === 'string' ? JSON.parse(row.template_json || '{}') : (row.template_json || {});
      pageKey = row.page_key;
    } else if (rows.length > 1) {
      // Multi-page app: without page_handle we can't disambiguate. Log which config_types exist for future fixing.
      console.warn('[loadFieldLabelsForCR] fallback: multiple config_templates rows and no page_handle/config_type_id bridge. Available page_keys:', rows.map(r => r.page_key));
    } else {
      console.warn('[loadFieldLabelsForCR] fallback: no config_templates rows for app_id=', appRow.id);
    }
  } catch (e) { console.warn('[loadFieldLabelsForCR] fallback fetch failed', e && e.message); }
}

if (!tplObj || !pageKey) { console.warn('[loadFieldLabelsForCR] gave up; domain=', domain, 'ph=', ph, 'cfgType=', cfgType); return null; }

cache[pageKey] = tplObj.field_labels || {};
await actions.setVariable('field_labels_by_page_key', cache);
console.log('[loadFieldLabelsForCR] cached', Object.keys(cache[pageKey]).length, 'labels for', pageKey);
return cache[pageKey];
